FightScript:
if (PlayerInfo.Strength<10)
        {
            return;
        }
        Vars["ThisCount"]="0";
        AddEvent("FightStart",(() => {SetStatus("Self");ChangeDynamicVar("DefaultDamage","6");}));
        AddEvent("AttackDone", () =>
        {
            if (Vars["ThisCount"]=="0")
            {
                Vars["ThisCount"]="1";
                ChangeDynamicVar("DefaultDamage","-6");
            }
        });

if (PlayerInfo.Perceive<40)
        {
            return;
        }
        AddEvent("FightStart",(() => {SetStatus("Self");AddBuff(DataId.buff_sourcecast,"1");

        }));
        AddEvent("StartRound",()=>{SetStatus("Self");foreach (var item in Object)
        {
            if (GetStatus.ContainsKey(item))
            {
                item.CurHp = GetStatus[item]["CurHp"];
                item.MaxHp = GetStatus[item]["MaxHp"];
            }
            else
            {
                GetStatus[item] = new Dictionary<string, int>
                {
                    { "CurHp", item.CurHp },
                    { "MaxHp", item.MaxHp },
                };
            }

        };});

if (PlayerInfo.Lucky<40)
        {
            return;
        }

        AddEvent("OnDiceValue", () =>
        {
            ValueDice.OnRoll += result =>
            {
                new Dice.State(result.Value + 10, result.Bonus).CopyTo(result);
            };
        });

        AddEvent("OnDiceCheck", () =>
        {
            CheckDice.OnRoll += result =>
            {
                new Dice.State(result.Value + 10, result.Bonus).CopyTo(result);
            };
        });

if (PlayerInfo.SpecialVars.ContainsKey(DataId.blessing_35) ||PlayerInfo.enemylevel==4)
        {
            return;
        }
        SetStatus("Self");
        AddEvent("Dead",()=> {
            if (!PlayerInfo.SpecialVars.ContainsKey(DataId.blessing_35))
            {
            SetStatus("AllFriends");
            int livePeople = 0;
            foreach (var item in Object)
            {
                if (item.state!=IStatusManager.State.Dead)
                {
                    livePeople++;
                }
            }
                if (livePeople==0&&Self.dynamicVariables["liveCount"]==0f&&((Self!=null&&Self.GetBuff(DataId.buff_rebirth)!=null&&Self.GetBuff(DataId.buff_rebirth).buffConfig.Level<30)||(Self!=null&&Self.GetBuff(DataId.buff_rebirth)==null)))
                {
                    Self.dynamicVariables["ResurrectionSource"] = 1f;
                    SetStatus("Self");
                    ChangeHp(Self.MaxHp.ToString());
                    Resurrection("100");
                    PlayerInfo.SpecialVars[DataId.blessing_35] = "1";
                EscapeFight();
                }

            }
        });

AddEvent("FightStart", () => {
            Vars["ThisCount"] = (int.Parse(Vars.GetValueOrDefault("ThisCount", "0")) + 1).ToString();
            if (int.Parse(Vars["ThisCount"]) < 4)
            {
                ChangeMaxHp("-4");
            }
            AddEvent("Escape", () =>
            {
                if (int.Parse(Vars["ThisCount"]) >=3)
                {
                    for (int i = 0; i < 3; i++)
                    {
                        PlayerInfo.AddBless(DataId.blessing_6);
                    PlayerInfo.AddBless(DataId.blessing_20);
                    }

                    PlayerInfo.RemoveBless(DataId.blessing_36);
                }
            });
            AddEvent("Win",()=> {
                if (int.Parse(Vars["ThisCount"]) >=3)
                {
                    for (int i = 0; i < 3; i++)
                    {
                        PlayerInfo.AddBless(DataId.blessing_6);
                    PlayerInfo.AddBless(DataId.blessing_20);
                    }

                    PlayerInfo.RemoveBless(DataId.blessing_36);
                }
            });
             });

if (PlayerInfo.enemylevel==4)
        {
            return;
        }
        ChangeDynamicVar("liveCount", "999");
        AddEvent("Dead",()=> {

                if (Self.dynamicVariables["liveCount"]==1f)
                {
                EscapeFight();
                }

        });

SetStatus("Self");SetStatus("Self");
        AddEvent<AddBuffData>("AddBuff",(d)=>{ if(d.data.data["Type"]!="负面"||d.toId==Self.InstanceId)return; 
 if(d.fromId!=Self.InstanceId||d.dataFromid==dataConfig.data["Id"])return; SetStatusById(d.toId); 
 int check = CheckDice.Roll().Value;
                if (check >90)
                {
                    SetStatusById(d.toId);
                    AddBuff(d.dataId, "1");
                }
                });

AddEvent("FightStart",(() => {SetStatus("Self");List<Dictionary<string,string>>cards=GetcardsByRarity("1","3");
        cards=cards.Where(x => x["Type"]!=("诅咒")).ToList();
        DataConfig newData=new DataConfig(cards[DefaultDice.WithRange(0, cards.Count - 1).Roll().Value]["Id"],DataType.Card);
        newData.Vars["Tag"]+=",Burnout";
        newData.Vars["TotalExCost"]="-999";
        CreateCard(newData);}));

Vars["ThisCount"] = "0";
 AddEvent("Action",() =>
 {
 Vars["ThisCount"] = (int.Parse(Vars["ThisCount"]) + 1).ToString();
 if (int.Parse(Vars["ThisCount"]) % 3 == 0)
 {
 SetStatus("Self");
 AddBuff(DataId.buff_rebirth, "1");
 }
 });

AddEvent("Hurt",() =>
 {
 if (Object.Count == 0 || Object[0] == null)
 {
 return;
 }
 var source = Object[0];
 if (source == Self)
 {
 return;
 }
 SetStatusById(source.InstanceId);
 AddBuff(DataId.buff_bleeding, "2");
 });
